#!/usr/bin/env python3
"""Create an isolated candidate registry snapshot; never mutate production registry."""
from __future__ import annotations
import argparse,copy,json
from pathlib import Path
def main():
 ap=argparse.ArgumentParser(); ap.add_argument('--production-registry',type=Path,required=True); ap.add_argument('--output',type=Path,required=True); ap.add_argument('--artifact-root',required=True); a=ap.parse_args(); reg=json.loads(a.production_registry.read_text(encoding='utf-8')); out=copy.deepcopy(reg); attrs=next(x for x in out['artifacts'] if x.get('role')=='attributes'); attrs.update({'artifact_id':'vehicle-attr-v28-merged-input224','delivery_status':'engine_validated','architecture':'MobileNetV3-Large isolated body/color head merge','files':{'onnx_path':a.artifact_root+'/merged-input224-calibrated.onnx','engine_path':a.artifact_root+'/merged-input224.engine','onnx_sha256':'see merged-input224-sha256.json','engine_sha256':'see merged-input224-sha256.json'},'provenance':{'dataset_version':'attribute-domain-v2-v29-independent-vcor','training_run_id':'ATTR-V28-MNV3-224-VCORCOLOR-ONLY+ATTR-V23-BMDRAW-TYPE','model_card_path':a.artifact_root+'/merged-input224-model-card.json','metrics_path':a.artifact_root+'/merged-input224-candidate-report.json','calibration_path':a.artifact_root+'/merged-calibration.json','parity_path':a.artifact_root+'/merged-input224-onnx-parity.json','track_report_path':'pending-independent-track-fusion'},'gates':{'independent_validation_test_calibration':'pass','onnx_top1_parity':'pass','tensorrt_deserialize_smoke':'pass','track_stability_rate':'pending','complex_color_unknown_reduction':'pending'}}); out['candidate_policy']={'production_registry_overwritten':False,'production_model':'vehicle-attr-agent-e-224','deployment_performed':False,'rollback_required_before_deploy':True,'frontend_backend_change_pause':True}; a.output.parent.mkdir(parents=True,exist_ok=True); a.output.write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n',encoding='utf-8'); print(json.dumps({'output':str(a.output),'production_registry_unchanged':True,'artifact_id':attrs['artifact_id']},ensure_ascii=False))
if __name__=='__main__': main()
